insert into public.quiz_questions (lesson_id, sort, prompt, options, correct_index, explanation) values
  ('sc-ps-01', 1, 'PowerShell commands follow the form…', '["Noun-Verb", "Verb-Noun", "just verbs", "random"]'::jsonb, 1, 'Cmdlets are Verb-Noun, e.g. Get-Process.'),
  ('sc-ps-01', 2, 'Which discovers available commands?', '["Get-Help", "Get-Command", "Write-Host", "Exit"]'::jsonb, 1, 'Get-Command lists/searches cmdlets.'),
  ('sc-ps-01', 3, 'To see usage examples for a cmdlet use…', '["Get-Help -Examples", "Get-Member", "Clear-Host", "Get-Date"]'::jsonb, 0, 'Get-Help <cmd> -Examples shows usage.'),
  ('sc-ps-02', 1, 'The pipeline passes what between cmdlets?', '["Plain text", "Objects", "Files", "Bytes"]'::jsonb, 1, 'PowerShell pipes rich objects.'),
  ('sc-ps-02', 2, 'Which filters objects by a condition?', '["Select-Object", "Where-Object", "Sort-Object", "Format-Table"]'::jsonb, 1, 'Where-Object filters by condition.'),
  ('sc-ps-02', 3, 'To see an object''s properties/methods, pipe to…', '["Get-Help", "Get-Member", "Get-Command", "Out-Null"]'::jsonb, 1, 'Get-Member reveals the object''s members.'),
  ('sc-ps-03', 1, 'Equality in PowerShell is written…', '["==", "-eq", "=", "eq"]'::jsonb, 1, '-eq tests equality (= assigns).'),
  ('sc-ps-03', 2, 'An array literal uses…', '["{ }", "@( )", "[ ]", "< >"]'::jsonb, 1, '@( ) creates an array.'),
  ('sc-ps-03', 3, 'A key/value collection is a…', '["array", "hashtable", "string", "tuple"]'::jsonb, 1, '@{} is a hashtable.'),
  ('sc-ps-04', 1, 'Inside ForEach-Object, the current item is…', '["$it", "$_", "$this", "$item"]'::jsonb, 1, '$_ (or $PSItem) is the current object.'),
  ('sc-ps-04', 2, 'Which handles multiple discrete cases cleanly?', '["for", "switch", "while", "break"]'::jsonb, 1, 'switch matches multiple cases.'),
  ('sc-ps-04', 3, 'foreach ($x in $coll) iterates…', '["once", "over each element", "backwards only", "never"]'::jsonb, 1, 'It runs the block per element.'),
  ('sc-ps-05', 1, 'Function parameters are declared with…', '["args()", "param()", "def", "input()"]'::jsonb, 1, 'param() defines function parameters.'),
  ('sc-ps-05', 2, 'PowerShell script files use the extension…', '["-.sh", "-.ps1", "-.py", "-.bat"]'::jsonb, 1, '.ps1 is a PowerShell script.'),
  ('sc-ps-05', 3, 'Scripts won''t run due to…', '["Low RAM", "Execution policy", "No mouse", "DNS"]'::jsonb, 1, 'Execution policy can block scripts.'),
  ('sc-ps-06', 1, 'Export objects to CSV with…', '["Write-Host", "Export-Csv", "Out-Null", "Format-Table"]'::jsonb, 1, 'Export-Csv writes objects to CSV.'),
  ('sc-ps-06', 2, 'Recurring automation on Windows uses…', '["Task Scheduler", "Paint", "Notepad", "DNS"]'::jsonb, 0, 'Task Scheduler runs scripts on a schedule.'),
  ('sc-ps-06', 3, 'Select-Object -First 5 returns…', '["last 5", "first 5 objects", "all", "none"]'::jsonb, 1, 'It takes the first 5 objects.'),
  ('sc-ps-07', 1, 'Which makes a cmdlet error catchable by try/catch?', '["-Force", "-ErrorAction Stop", "-WhatIf", "-Confirm"]'::jsonb, 1, 'Non-terminating errors need -ErrorAction Stop to be caught.'),
  ('sc-ps-07', 2, 'Code that must always run goes in…', '["try", "catch", "finally", "trap"]'::jsonb, 2, 'finally always executes.'),
  ('sc-ps-07', 3, 'The most recent error is in…', '["$LastError", "$Error[0]", "$?", "$_"]'::jsonb, 1, '$Error[0] holds the latest error.'),
  ('sc-ps-08', 1, 'Which runs a scriptblock on a remote host?', '["Enter-Host", "Invoke-Command", "Run-Remote", "Get-Session"]'::jsonb, 1, 'Invoke-Command -ComputerName runs remotely.'),
  ('sc-ps-08', 2, 'Third-party modules install from…', '["the BIOS", "PowerShell Gallery", "Task Scheduler", "the registry"]'::jsonb, 1, 'Install-Module pulls from PSGallery.'),
  ('sc-ps-08', 3, 'A reusable, persistent remote connection is a…', '["job", "PSSession", "pipe", "cmdlet"]'::jsonb, 1, 'New-PSSession creates a reusable session.'),
  ('sc-ps-09', 1, 'A required parameter uses…', '["[Optional]", "[Parameter(Mandatory)]", "[Switch]", "[AllowNull]"]'::jsonb, 1, '[Parameter(Mandatory)] forces a value.'),
  ('sc-ps-09', 2, 'A safe dry-run is enabled by supporting…', '["-Force", "-WhatIf", "-Quiet", "-Silent"]'::jsonb, 1, '-WhatIf previews without acting.'),
  ('sc-ps-09', 3, 'Recurring script execution is handled by…', '["Task Scheduler", "Notepad", "the pipeline", "Get-Help"]'::jsonb, 0, 'Task Scheduler runs scripts on a schedule.'),
  ('sc-ps-10', 1, 'List files recursively with…', '["Get-Item", "Get-ChildItem -Recurse", "dir /s only", "Find-File"]'::jsonb, 1, 'Get-ChildItem -Recurse walks subfolders.'),
  ('sc-ps-10', 2, 'Filter to files over 1MB uses…', '["Where-Object Length -gt 1MB", "Select big", "-Large", "Sort-Size"]'::jsonb, 0, 'Where-Object filters on the Length property.'),
  ('sc-ps-10', 3, '(Get-Date).AddDays(-30) gives…', '["30 days ahead", "30 days ago", "today", "an error"]'::jsonb, 1, 'Negative days subtract from now.'),
  ('sc-ps-11', 1, 'Restart a service with…', '["Reset-Service", "Restart-Service", "Cycle-Service", "Bounce-Service"]'::jsonb, 1, 'Restart-Service stops then starts it.'),
  ('sc-ps-11', 2, 'Kill a process by name…', '["Stop-Process -Name", "End-Task", "Kill-Process", "Remove-Process"]'::jsonb, 0, 'Stop-Process -Name <n> -Force.'),
  ('sc-ps-11', 3, 'Set a service to auto-start via…', '["Set-Service -StartupType Automatic", "Auto-Service", "Enable-Service", "Start-Type"]'::jsonb, 0, 'Set-Service -StartupType Automatic.'),
  ('sc-ps-12', 1, 'Modern event querying uses…', '["Get-WinEvent", "Read-Log", "Get-Text", "Event-View"]'::jsonb, 0, 'Get-WinEvent is the modern cmdlet.'),
  ('sc-ps-12', 2, 'Registry is accessed via which drive prefix?', '["C:\\", "HKLM:\\ / HKCU:\\", "REG:\\", "SYS:\\"]'::jsonb, 1, 'PowerShell exposes the registry as HKLM:/HKCU: drives.'),
  ('sc-ps-12', 3, 'Level=2 in a System log filter means…', '["Info", "Warning", "Error", "Verbose"]'::jsonb, 2, 'Level 2 = Error.'),
  ('sc-ps-13', 1, 'Ping in PowerShell is…', '["Ping-Host", "Test-Connection", "Send-Ping", "Net-Ping"]'::jsonb, 1, 'Test-Connection sends ICMP echo.'),
  ('sc-ps-13', 2, 'Test a specific TCP port with…', '["Test-NetConnection -Port", "Test-Port", "Get-Port", "Check-Port"]'::jsonb, 0, 'Test-NetConnection -Port checks a port.'),
  ('sc-ps-13', 3, 'Resolve a name to IP with…', '["Resolve-DnsName", "Get-DNS", "Lookup-Name", "Find-Host"]'::jsonb, 0, 'Resolve-DnsName queries DNS.'),
  ('sc-ps-14', 1, 'Find locked-out accounts with…', '["Search-ADAccount -LockedOut", "Get-Locked", "Find-Lock", "AD-Locked"]'::jsonb, 0, 'Search-ADAccount -LockedOut lists them.'),
  ('sc-ps-14', 2, 'Add a user to a group via…', '["Add-ADGroupMember", "Join-Group", "Set-Group", "Group-Add"]'::jsonb, 0, 'Add-ADGroupMember -Members.'),
  ('sc-ps-14', 3, 'Offboarding disables an account with…', '["Remove-ADUser", "Disable-ADAccount", "Stop-ADUser", "Lock-Account"]'::jsonb, 1, 'Disable-ADAccount disables without deleting.'),
  ('sc-ps-15', 1, 'Register a recurring task with…', '["Register-ScheduledTask", "Add-Task", "New-Cron", "Schedule-Run"]'::jsonb, 0, 'Register-ScheduledTask creates it.'),
  ('sc-ps-15', 2, 'Modern replacement for Get-WmiObject is…', '["Get-CimInstance", "Get-WMI2", "Get-System", "Get-Info"]'::jsonb, 0, 'Get-CimInstance is the modern cmdlet.'),
  ('sc-ps-15', 3, 'Win32_LogicalDisk exposes…', '["CPU temp", "Disk space", "AD users", "Event logs"]'::jsonb, 1, 'It reports disk size/free space.'),
  ('sc-ps-16', 1, 'Read a CSV into objects with…', '["Import-Csv", "Read-Csv", "Get-Csv", "Open-Csv"]'::jsonb, 0, 'Import-Csv parses rows into objects.'),
  ('sc-ps-16', 2, 'Parse JSON text with…', '["ConvertFrom-Json", "Parse-Json", "Read-Json", "Get-Json"]'::jsonb, 0, 'ConvertFrom-Json builds objects.'),
  ('sc-ps-16', 3, 'Export objects to CSV with…', '["Export-Csv -NoTypeInformation", "Save-Csv", "Write-Csv", "Out-Csv"]'::jsonb, 0, 'Export-Csv writes objects to CSV.'),
  ('sc-ps-17', 1, 'Rounding free bytes to GB uses…', '["[math]::Round($x/1GB,1)", "/1000", "Round-GB", "ToGB()"]'::jsonb, 0, 'Divide by 1GB and [math]::Round.'),
  ('sc-ps-17', 2, 'The report is made recurring by…', '["Register-ScheduledTask", "a while loop", "manual runs", "Task-Loop"]'::jsonb, 0, 'Schedule it with Register-ScheduledTask.'),
  ('sc-ps-17', 3, 'Robust scripts wrap logic in…', '["try/catch + logging", "nothing", "comments only", "a GUI"]'::jsonb, 0, 'Error handling + logging make it production-safe.'),
  ('sc-ps-18', 1, 'Which auto-parses JSON into objects?', '["Invoke-WebRequest", "Invoke-RestMethod", "Get-Web", "Fetch-Url"]'::jsonb, 1, 'Invoke-RestMethod parses JSON responses.'),
  ('sc-ps-18', 2, 'A POST body is usually sent as…', '["plain text", "JSON via ConvertTo-Json", "CSV", "XML only"]'::jsonb, 1, 'Convert a hashtable to JSON for the body.'),
  ('sc-ps-18', 3, 'Auth tokens go in the…', '["URL only", "Headers", "Body", "Filename"]'::jsonb, 1, 'Authorization header carries the token.'),
  ('sc-ps-19', 1, 'Grep-like search in PowerShell is…', '["Find-Text", "Select-String", "Search-Log", "Match-Line"]'::jsonb, 1, 'Select-String matches patterns in text.'),
  ('sc-ps-19', 2, 'Tally values by frequency with…', '["Group-Object", "Count-Object", "Sum-Object", "Tally"]'::jsonb, 0, 'Group-Object buckets by value.'),
  ('sc-ps-19', 3, 'Regex capture groups are accessed via…', '["$_.Matches.Groups", "$_.Text", "$_.Line only", "$_.Value[0]"]'::jsonb, 0, 'Matches.Groups holds captures.'),
  ('sc-ps-20', 1, 'Free space % comes from…', '["FreeSpace / Size * 100", "FreeSpace only", "Size - 100", "random"]'::jsonb, 0, 'Free/Size*100 gives the percentage.'),
  ('sc-ps-20', 2, 'A monitor reacts when a value crosses a…', '["color", "threshold", "font", "port"]'::jsonb, 1, 'Thresholds trigger alerts.'),
  ('sc-ps-20', 3, 'Monitors are typically run…', '["once manually", "on a schedule", "never", "at install only"]'::jsonb, 1, 'Scheduled runs catch issues early.'),
  ('sc-ps-21', 1, 'Create a zip archive with…', '["Compress-Archive", "Zip-Item", "New-Zip", "Archive-File"]'::jsonb, 0, 'Compress-Archive builds a .zip.'),
  ('sc-ps-21', 2, 'Dated filenames use…', '["Get-Date -Format", "Now()", "Date-Stamp", "Time-Tag"]'::jsonb, 0, 'Get-Date -Format yyyyMMdd.'),
  ('sc-ps-21', 3, 'Retention is enforced by deleting files older than…', '["a threshold date", "never", "1 hour", "the newest"]'::jsonb, 0, 'Remove archives past the retention window.'),
  ('sc-ps-22', 1, 'List all GPOs with…', '["Get-GPO -All", "Get-Policy", "List-GPO", "GPO-All"]'::jsonb, 0, 'Get-GPO -All enumerates them.'),
  ('sc-ps-22', 2, 'Export a GPO to HTML with…', '["Get-GPOReport -ReportType Html", "Export-GPO", "Save-GPO", "GPO-Html"]'::jsonb, 0, 'Get-GPOReport -ReportType Html.'),
  ('sc-ps-22', 3, 'Applied policy on a client is shown by…', '["gpresult /r", "gpo /list", "policy /show", "rsop /r"]'::jsonb, 0, 'gpresult /r lists applied GPOs.'),
  ('sc-ps-23', 1, 'Preview a destructive command with…', '["-WhatIf", "-Force", "-Quiet", "-Yes"]'::jsonb, 0, '-WhatIf shows what would happen.'),
  ('sc-ps-23', 2, 'Traceable step-by-step output uses…', '["-Verbose", "-Silent", "-Debug off", "-Fast"]'::jsonb, 0, '-Verbose emits progress detail.'),
  ('sc-ps-23', 3, 'Uptime comes from Win32_OperatingSystem''s…', '["LastBootUpTime", "Uptime", "BootDate", "StartTime"]'::jsonb, 0, 'LastBootUpTime gives boot time.'),
  ('sc-ps-24', 1, 'A PowerShell module file uses the extension…', '["-.ps1", ".psm1", ".mod", "-.dll"]'::jsonb, 1, '.psm1 is a script module.'),
  ('sc-ps-24', 2, 'Expose functions from a module with…', '["Export-ModuleMember", "Publish-Function", "Show-Function", "Export-Func"]'::jsonb, 0, 'Export-ModuleMember -Function.'),
  ('sc-ps-24', 3, 'Load a module with…', '["Import-Module", "Load-Module", "Use-Module", "Add-Module"]'::jsonb, 0, 'Import-Module brings it into the session.'),
